/**
*@filelibavformatandlibavcodecdemuxinganddecodingAPIusageexample
*@exampledemux_decode.c
*
*ShowhowtousethelibavformatandlibavcodecAPItodemuxanddecodeaudio
*andvideodata.Writetheoutputasrawaudioandinputfilestobeplayedby
*ffplay.
*/

#include<libavutil/imgutils.h>
#include<libavutil/samplefmt.h>
#include<libavutil/timestamp.h>
#include<libavcodec/avcodec.h>
#include<libavformat/avformat.h>

staticAVFormatContext*fmt_ctx=NULL;
staticAVCodecContext*video_dec_ctx=NULL,*audio_dec_ctx;
staticintwidth,height;
staticenumAVPixelFormatpix_fmt;
staticAVStream*video_stream=NULL,*audio_stream=NULL;
staticconstchar*src_filename=NULL;
staticconstchar*video_dst_filename=NULL;
staticconstchar*audio_dst_filename=NULL;
staticFILE*video_dst_file=NULL;
staticFILE*audio_dst_file=NULL;

staticuint8_t*video_dst_data[4]={NULL};
staticintvideo_dst_linesize[4];
staticintvideo_dst_bufsize;

staticintvideo_stream_idx=-1,audio_stream_idx=-1;
staticAVFrame*frame=NULL;
staticAVPacket*pkt=NULL;
staticintvideo_frame_count=0;
staticintaudio_frame_count=0;

staticintoutput_video_frame(AVFrame*frame)
{
if(frame->width!=width||frame->height!=height||
frame->format!=pix_fmt){
/*Tohandlethischange,onecouldcallav_image_allocagainand
*decodethefollowingframesintoanotherrawvideofile.*/
fprintf(stderr,"Error:Width,heightandpixelformathavetobe"
"constantinarawvideofile,butthewidth,heightor"
"pixelformatoftheinputvideochanged:\n"
"old:width=%d,height=%d,format=%s\n"
"new:width=%d,height=%d,format=%s\n",
width,height,av_get_pix_fmt_name(pix_fmt),
frame->width,frame->height,
av_get_pix_fmt_name(frame->format));
return-1;
}

printf("video_framen:%d\n",
video_frame_count++);

/*copydecodedframetodestinationbuffer:
*thisisrequiredsincerawvideoexpectsnonaligneddata*/
av_image_copy2(video_dst_data,video_dst_linesize,
frame->data,frame->linesize,
pix_fmt,width,height);

/*writetorawvideofile*/
fwrite(video_dst_data[0],1,video_dst_bufsize,video_dst_file);
return0;
}

staticintoutput_audio_frame(AVFrame*frame)
{
size_tunpadded_linesize=frame->nb_samples*av_get_bytes_per_sample(frame->format);
printf("audio_framen:%dnb_samples:%dpts:%s\n",
audio_frame_count++,frame->nb_samples,
av_ts2timestr(frame->pts,&audio_dec_ctx->time_base));

/*Writetherawaudiodatasamplesofthefirstplane.Thisworks
*fineforpackedformats(e.g.AV_SAMPLE_FMT_S16).However,
*mostaudiodecodersoutputplanaraudio,whichusesaseparate
*planeofaudiosamplesforeachchannel(e.g.AV_SAMPLE_FMT_S16P).
*Inotherwords,thiscodewillwriteonlythefirstaudiochannel
*inthesecases.
*Youshoulduselibswresampleorlibavfiltertoconverttheframe
*topackeddata.*/
fwrite(frame->extended_data[0],1,unpadded_linesize,audio_dst_file);

return0;
}

staticintdecode_packet(AVCodecContext*dec,constAVPacket*pkt)
{
intret=0;

//submitthepackettothedecoder
ret=avcodec_send_packet(dec,pkt);
if(ret<0){
fprintf(stderr,"Errorsubmittingapacketfordecoding(%s)\n",av_err2str(ret));
returnret;
}

//getalltheavailableframesfromthedecoder
while(ret>=0){
ret=avcodec_receive_frame(dec,frame);
if(ret<0){
//thosetworeturnvaluesarespecialandmeanthereisnooutput
//frameavailable,buttherewerenoerrorsduringdecoding
if(ret==AVERROR_EOF||ret==AVERROR(EAGAIN))
return0;

fprintf(stderr,"Errorduringdecoding(%s)\n",av_err2str(ret));
returnret;
}

//writetheframedatatooutputfile
if(dec->codec->type==AVMEDIA_TYPE_VIDEO)
ret=output_video_frame(frame);
else
ret=output_audio_frame(frame);

av_frame_unref(frame);
}

returnret;
}

staticintopen_codec_context(int*stream_idx,
AVCodecContext**dec_ctx,AVFormatContext*fmt_ctx,enumAVMediaTypetype)
{
intret,stream_index;
AVStream*st;
constAVCodec*dec=NULL;

ret=av_find_best_stream(fmt_ctx,type,-1,-1,NULL,0);
if(ret<0){
fprintf(stderr,"Couldnotfind%sstreamininputfile'%s'\n",
av_get_media_type_string(type),src_filename);
returnret;
}else{
stream_index=ret;
st=fmt_ctx->streams[stream_index];

/*finddecoderforthestream*/
dec=avcodec_find_decoder(st->codecpar->codec_id);
if(!dec){
fprintf(stderr,"Failedtofind%scodec\n",
av_get_media_type_string(type));
returnAVERROR(EINVAL);
}

/*Allocateacodeccontextforthedecoder*/
*dec_ctx=avcodec_alloc_context3(dec);
if(!*dec_ctx){
fprintf(stderr,"Failedtoallocatethe%scodeccontext\n",
av_get_media_type_string(type));
returnAVERROR(ENOMEM);
}

/*Copycodecparametersfrominputstreamtooutputcodeccontext*/
if((ret=avcodec_parameters_to_context(*dec_ctx,st->codecpar))<0){
fprintf(stderr,"Failedtocopy%scodecparameterstodecodercontext\n",
av_get_media_type_string(type));
returnret;
}

/*Initthedecoders*/
if((ret=avcodec_open2(*dec_ctx,dec,NULL))<0){
fprintf(stderr,"Failedtoopen%scodec\n",
av_get_media_type_string(type));
returnret;
}
*stream_idx=stream_index;
}

return0;
}

staticintget_format_from_sample_fmt(constchar**fmt,
enumAVSampleFormatsample_fmt)
{
inti;
structsample_fmt_entry{
enumAVSampleFormatsample_fmt;constchar*fmt_be,*fmt_le;
}sample_fmt_entries[]={
{AV_SAMPLE_FMT_U8,"u8","u8"},
{AV_SAMPLE_FMT_S16,"s16be","s16le"},
{AV_SAMPLE_FMT_S32,"s32be","s32le"},
{AV_SAMPLE_FMT_FLT,"f32be","f32le"},
{AV_SAMPLE_FMT_DBL,"f64be","f64le"},
};
*fmt=NULL;

for(i=0;i<FF_ARRAY_ELEMS(sample_fmt_entries);i++){
structsample_fmt_entry*entry=&sample_fmt_entries[i];
if(sample_fmt==entry->sample_fmt){
*fmt=AV_NE(entry->fmt_be,entry->fmt_le);
return0;
}
}

fprintf(stderr,
"sampleformat%sisnotsupportedasoutputformat\n",
av_get_sample_fmt_name(sample_fmt));
return-1;
}

intmain(intargc,char**argv)
{
intret=0;

if(argc!=4){
fprintf(stderr,"usage:%sinput_filevideo_output_fileaudio_output_file\n"
"APIexampleprogramtoshowhowtoreadframesfromaninputfile.\n"
"Thisprogramreadsframesfromafile,decodesthem,andwritesdecoded\n"
"videoframestoarawvideofilenamedvideo_output_file,anddecoded\n"
"audioframestoarawaudiofilenamedaudio_output_file.\n",
argv[0]);
exit(1);
}
src_filename=argv[1];
video_dst_filename=argv[2];
audio_dst_filename=argv[3];

/*openinputfile,andallocateformatcontext*/
if(avformat_open_input(&fmt_ctx,src_filename,NULL,NULL)<0){
fprintf(stderr,"Couldnotopensourcefile%s\n",src_filename);
exit(1);
}

/*retrievestreaminformation*/
if(avformat_find_stream_info(fmt_ctx,NULL)<0){
fprintf(stderr,"Couldnotfindstreaminformation\n");
exit(1);
}

if(open_codec_context(&video_stream_idx,&video_dec_ctx,fmt_ctx,AVMEDIA_TYPE_VIDEO)>=0){
video_stream=fmt_ctx->streams[video_stream_idx];

video_dst_file=fopen(video_dst_filename,"wb");
if(!video_dst_file){
fprintf(stderr,"Couldnotopendestinationfile%s\n",video_dst_filename);
ret=1;
gotoend;
}

/*allocateimagewherethedecodedimagewillbeput*/
width=video_dec_ctx->width;
height=video_dec_ctx->height;
pix_fmt=video_dec_ctx->pix_fmt;
ret=av_image_alloc(video_dst_data,video_dst_linesize,
width,height,pix_fmt,1);
if(ret<0){
fprintf(stderr,"Couldnotallocaterawvideobuffer\n");
gotoend;
}
video_dst_bufsize=ret;
}

if(open_codec_context(&audio_stream_idx,&audio_dec_ctx,fmt_ctx,AVMEDIA_TYPE_AUDIO)>=0){
audio_stream=fmt_ctx->streams[audio_stream_idx];
audio_dst_file=fopen(audio_dst_filename,"wb");
if(!audio_dst_file){
fprintf(stderr,"Couldnotopendestinationfile%s\n",audio_dst_filename);
ret=1;
gotoend;
}
}

/*dumpinputinformationtostderr*/
av_dump_format(fmt_ctx,0,src_filename,0);

if(!audio_stream&&!video_stream){
fprintf(stderr,"Couldnotfindaudioorvideostreamintheinput,aborting\n");
ret=1;
gotoend;
}

frame=av_frame_alloc();
if(!frame){
fprintf(stderr,"Couldnotallocateframe\n");
ret=AVERROR(ENOMEM);
gotoend;
}

pkt=av_packet_alloc();
if(!pkt){
fprintf(stderr,"Couldnotallocatepacket\n");
ret=AVERROR(ENOMEM);
gotoend;
}

if(video_stream)
printf("Demuxingvideofromfile'%s'into'%s'\n",src_filename,video_dst_filename);
if(audio_stream)
printf("Demuxingaudiofromfile'%s'into'%s'\n",src_filename,audio_dst_filename);

/*readframesfromthefile*/
while(av_read_frame(fmt_ctx,pkt)>=0){
//checkifthepacketbelongstoastreamweareinterestedin,otherwise
//skipit
if(pkt->stream_index==video_stream_idx)
ret=decode_packet(video_dec_ctx,pkt);
elseif(pkt->stream_index==audio_stream_idx)
ret=decode_packet(audio_dec_ctx,pkt);
av_packet_unref(pkt);
if(ret<0)
break;
}

/*flushthedecoders*/
if(video_dec_ctx)
decode_packet(video_dec_ctx,NULL);
if(audio_dec_ctx)
decode_packet(audio_dec_ctx,NULL);

printf("Demuxingsucceeded.\n");

if(video_stream){
printf("Playtheoutputvideofilewiththecommand:\n"
"ffplay-frawvideo-pix_fmt%s-video_size%dx%d%s\n",
av_get_pix_fmt_name(pix_fmt),width,height,
video_dst_filename);
}

if(audio_stream){
enumAVSampleFormatsfmt=audio_dec_ctx->sample_fmt;
intn_channels=audio_dec_ctx->ch_layout.nb_channels;
constchar*fmt;

if(av_sample_fmt_is_planar(sfmt)){
constchar*packed=av_get_sample_fmt_name(sfmt);
printf("Warning:thesampleformatthedecoderproducedisplanar"
"(%s).Thisexamplewilloutputthefirstchannelonly.\n",
packed?packed:"?");
sfmt=av_get_packed_sample_fmt(sfmt);
n_channels=1;
}

if((ret=get_format_from_sample_fmt(&fmt,sfmt))<0)
gotoend;

printf("Playtheoutputaudiofilewiththecommand:\n"
"ffplay-f%s-ac%d-ar%d%s\n",
fmt,n_channels,audio_dec_ctx->sample_rate,
audio_dst_filename);
}

end:
avcodec_free_context(&video_dec_ctx);
avcodec_free_context(&audio_dec_ctx);
avformat_close_input(&fmt_ctx);
if(video_dst_file)
fclose(video_dst_file);
if(audio_dst_file)
fclose(audio_dst_file);
av_packet_free(&pkt);
av_frame_free(&frame);
av_free(video_dst_data[0]);

returnret<0;
}
